    std::uint8_t *aEarthLaneB = pWorkSpace->mEarthLaneB;
    std::uint8_t *aEarthLaneC = pWorkSpace->mEarthLaneC;
    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xB5CB5700B6AD2861ULL + 0x9065E37D904B60AFULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0xD275598B9AECE3F9ULL + 0x863B80D55A7E70E9ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseA(pNonce * 0xC69F4779E2ABA63BULL + 0xA850F35843674FD8ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseA(pNonce * 0x870E02AE943C0CC5ULL + 0xE04CAC6B4F3339E5ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseC(pNonce * 0xBD92F69D994709DBULL + 0xA587272CEC6E1E1EULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseA(pNonce * 0xFC1A4F1576E573EFULL + 0xDF935D7F2908FA34ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseB(pNonce * 0xB58C40C2A27AA097ULL + 0xADC36934747BFF28ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordH = TwistMix64::DiffuseC(pNonce * 0x829ADCED56174A0FULL + 0xCD16D3BAE54205A4ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordI = TwistMix64::DiffuseB(pNonce * 0xC2F81125E34F3DF9ULL + 0xE5AA2187E6186DF8ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordJ = TwistMix64::DiffuseB(pNonce * 0x9892845F43760E33ULL + 0xB42588E4E24481E1ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordK = TwistMix64::DiffuseA(pNonce * 0xA309442A11ABFF65ULL + 0xA1E57D5ED57FC204ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordL = TwistMix64::DiffuseB(pNonce * 0xB61239A99237C4B7ULL + 0x84AA80761633EDCCULL);
    [[maybe_unused]] const std::uint64_t aNonceWordM = TwistMix64::DiffuseA(pNonce * 0xA237BA6353AF5EBBULL + 0xEF3D4D96839354EBULL);
    [[maybe_unused]] const std::uint64_t aNonceWordN = TwistMix64::DiffuseC(pNonce * 0x80C04D0D5D5A850DULL + 0xC62E2354F9C35BAFULL);
    [[maybe_unused]] const std::uint64_t aNonceWordO = TwistMix64::DiffuseB(pNonce * 0xF9121FCB4D10B297ULL + 0xF92DE135C725FFCCULL);
    [[maybe_unused]] const std::uint64_t aNonceWordP = TwistMix64::DiffuseB(pNonce * 0xB40695BEA9BB8B6FULL + 0xD66C19716A011E7AULL);
    std::uint64_t aDomainWordIngress = pConstants->mIngress;
