            aIngress ^= (RotL64(aMagmaLaneA[((aIndex + 4094U)) & S_BLOCK1], 6U) ^ RotL64(aCrystalLaneD[((aIndex + 2284U)) & S_BLOCK1], 57U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 7379U)) & S_BLOCK1], 54U) ^ RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 4865U)) & S_BLOCK1], 43U));
            aCross ^= (RotL64(aLightningLaneD[((S_BLOCK1 - aIndex + 3431U)) & S_BLOCK1], 21U) ^ RotL64(aMagmaLaneB[((aIndex + 3430U)) & S_BLOCK1], 29U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 5U) ^ RotL64(aCross, 57U)) ^ (RotL64(aCarry, 26U) + RotL64(aIngress, 39U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterC = (((aWandererI + RotL64(aIngress, 19U)) + RotL64(aCarry, 27U)) + 0x11E58C1F18C8C924ULL) + aOASaltH[((aIndex + 85U)) & S_SALT1];
            aOrbiterJ = (((aWandererJ + RotL64(aPrevious, 43U)) + RotL64(aCarry, 47U)) + 0x3C45FD74CDDDF41EULL) + aOASaltD[((aIndex + 41U)) & S_SALT1];
            aOrbiterD = (aWandererG + RotL64(aScatter, 13U)) + 0x8E2E929C609C575AULL;
            aOrbiterA = (((aWandererE + RotL64(aCross, 28U)) + RotL64(aCarry, 3U)) + 0xB421C706B6F298A4ULL) + aOASaltG[(((511U - aIndex) + 211U)) & S_SALT1];
            aOrbiterB = (aWandererC + RotL64(aPrevious, 5U)) + 0xE472AEB28D983E7AULL;
            aOrbiterG = ((aWandererF + RotL64(aScatter, 35U)) + 0xE623B66BAFC08929ULL) + aOASaltE[((aIndex + 25U)) & S_SALT1];
            aOrbiterF = (aWandererK + RotL64(aIngress, 53U)) + 0xB7243B049DF09901ULL;
            //
            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0x31B3D99DBAE06919ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0x3249744B933D6A19ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xF02F07565B28D729ULL), 53U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0xEB7EC78A56356BA1ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x8B639DB5176049EEULL;
            aOrbiterB = RotL64((aOrbiterB * 0x18B66D94EC874317ULL), 3U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterD) + 0x9812774CD73484D8ULL) + aOUSaltA[(((511U - aIndex) + 26U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x4BA624EBF265CEC9ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x1C444A3A6BA05715ULL), 41U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0xAA0AE5835F33830DULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0xD6544D37873A4A50ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x7DA8B70D2252B1C5ULL), 47U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0x707563EC1E2C3BDBULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterJ) ^ 0x2FE250BC17DAEB0DULL) ^ aOUSaltB[(((511U - aIndex) + 356U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xB24171CA0D550453ULL), 21U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0xAB42EFBB62E5A9B3ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterB) ^ 0x9F3458ED79912B9AULL) ^ aOUSaltC[((aIndex + 235U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xEE56873809F8C375ULL), 11U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterC) + 0xBA27637716195EA2ULL) + aOUSaltF[((aIndex + 414U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x919E0614619CB843ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x5AE94F72EBD66619ULL), 35U);
            //
            aIngress = aOrbiterJ ^ RotL64(aOrbiterB, 53U);
            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterF, 47U));
            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterG, 11U));
            aIngress = aIngress + RotL64(aOrbiterC, 5U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererF = aWandererF ^ (((RotL64(aIngress, 37U) + RotL64(aOrbiterD, 53U)) + aOrbiterC) + aWUSaltB[(((511U - aIndex) + 462U)) & S_SALT1]);
            aWandererI = aWandererI + ((((RotL64(aScatter, 50U) + aOrbiterF) + RotL64(aOrbiterG, 37U)) + RotL64(aCarry, 5U)) + aWUSaltA[((aIndex + 412U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 57U) + aOrbiterG) + RotL64(aOrbiterC, 21U));
            aWandererE = aWandererE + (((RotL64(aCross, 11U) + RotL64(aOrbiterB, 43U)) + aOrbiterF) + aWUSaltC[((aIndex + 203U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 43U) + RotL64(aOrbiterJ, 13U)) + aOrbiterF);
            aWandererG = aWandererG + (((RotL64(aCross, 5U) + RotL64(aOrbiterG, 29U)) + aOrbiterA) + RotL64(aCarry, 37U));
            aWandererC = aWandererC ^ ((RotL64(aScatter, 27U) + RotL64(aOrbiterA, 4U)) + aOrbiterJ);
