            aIngress ^= (RotL64(aCrystalLaneA[((aIndex + 12220U)) & S_BLOCK1], 41U) ^ RotL64(aKeyRowReadB[((aIndex + 9008U)) & W_KEY1], 53U));
            aIngress = TwistMix64::DiffuseB((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 11230U)) & S_BLOCK1], 5U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 9387U)) & S_BLOCK1], 53U));
            aCross ^= (RotL64(aCrystalLaneB[((S_BLOCK1 - aIndex + 12516U)) & S_BLOCK1], 29U) ^ RotL64(aShadowLaneD[((S_BLOCK1 - aIndex + 13091U)) & S_BLOCK1], 40U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 51U) + RotL64(aPrevious, 23U)) ^ (RotL64(aIngress, 37U) ^ RotL64(aCarry, 6U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterB = (((aWandererF + RotL64(aCross, 5U)) + RotL64(aCarry, 43U)) + 0xC34E785A48462551ULL) + aOASaltD[((aIndex + 167U)) & S_SALT1];
            aOrbiterD = (aWandererK + RotL64(aPrevious, 60U)) + 0x7B5AC20A67EF9C9EULL;
            aOrbiterJ = ((aWandererJ + RotL64(aScatter, 27U)) + 0x413581610A5DEBBBULL) + aOASaltA[(((511U - aIndex) + 444U)) & S_SALT1];
            aOrbiterI = (((aWandererC + RotL64(aIngress, 21U)) + RotL64(aCarry, 21U)) + 0x73C0EA2B6B5FD2ABULL) + aOASaltF[((aIndex + 85U)) & S_SALT1];
            aOrbiterE = ((aWandererE + RotL64(aCross, 13U)) + 0x0B21BBF961070E8DULL) + aOASaltG[(((511U - aIndex) + 214U)) & S_SALT1];
            aOrbiterH = ((aWandererG + RotL64(aScatter, 37U)) + 0x39B843C9C781B227ULL) + aOASaltE[(((511U - aIndex) + 331U)) & S_SALT1];
            aOrbiterG = ((aWandererA + RotL64(aPrevious, 43U)) + RotL64(aCarry, 3U)) + 0xE49C1BBBA392D9D5ULL;
            //
            aOrbiterB = ((aOrbiterB + aOrbiterD) + 0xDFBE425ABE51197EULL) + aOUSaltG[((aIndex + 412U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x38E766458B1BDB6CULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xB203C2457BF7E197ULL), 39U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0xC158CDC4C4C22767ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterI) ^ 0x4E8B75DDA5661F7BULL) ^ aOUSaltE[((aIndex + 311U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xD32454C37B498CBBULL), 29U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0xAF7CB4E6C1EF4454ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0x70B96F78322AE3E0ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xAE502461C90F150DULL), 47U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x61B1586558628D3DULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0xCE36E0E30BF5C712ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x03AFCEBEAA07661FULL), 23U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterI) + 0x26F9053BC19110A7ULL) + aOUSaltC[(((511U - aIndex) + 57U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0x4C786F934C7CD1C7ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x284DE4F4B035B46BULL), 11U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0x8C4BF0130B025C73ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterG) ^ 0x29A98ECD0F6D29AAULL) ^ aOUSaltA[(((511U - aIndex) + 466U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x7EBC207E1D9D8A2DULL), 5U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0xD845DF7290180EF6ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0x1DB901493B7CA832ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x8D683811A0836BC9ULL), 57U);
            //
            aIngress = RotL64(aOrbiterH, 53U) ^ aOrbiterE;
            aIngress = aIngress + (RotL64(aOrbiterI, 11U) ^ aOrbiterB);
            aIngress = aIngress + (RotL64(aOrbiterG, 5U) ^ aOrbiterJ);
            aIngress = aIngress + RotL64(aOrbiterD, 26U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererC = aWandererC + ((RotL64(aPrevious, 19U) + aOrbiterE) + RotL64(aOrbiterG, 21U));
            aWandererA = aWandererA ^ (((RotL64(aIngress, 36U) + RotL64(aOrbiterJ, 35U)) + aOrbiterG) + aWUSaltA[(((511U - aIndex) + 107U)) & S_SALT1]);
            aWandererG = aWandererG + (((RotL64(aScatter, 27U) + RotL64(aOrbiterD, 43U)) + aOrbiterG) + aWUSaltE[(((511U - aIndex) + 367U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aCross, 53U) + aOrbiterE) + RotL64(aOrbiterH, 27U));
            aWandererF = aWandererF + (((RotL64(aIngress, 5U) + RotL64(aOrbiterB, 5U)) + aOrbiterI) + RotL64(aCarry, 53U));
            aWandererE = aWandererE ^ (((RotL64(aCross, 11U) + aOrbiterI) + RotL64(aOrbiterJ, 60U)) + aWUSaltB[((aIndex + 285U)) & S_SALT1]);
            aWandererJ = aWandererJ + (((RotL64(aPrevious, 43U) + RotL64(aOrbiterH, 11U)) + aOrbiterJ) + RotL64(aCarry, 21U));
