            aOrbiterB = ((aWandererE + RotL64(aIngress, 19U)) + RotL64(aCarry, 27U)) + 0x97862F66762B68F3ULL;
            aOrbiterA = (aWandererI + RotL64(aPrevious, 14U)) + 0xC395AD6D7EE94638ULL;
            //
            aOrbiterF = ((aOrbiterF + aOrbiterD) + 0x23829DB6C9A3CB24ULL) + aOUSaltF[((aIndex + 333U)) & S_SALT1];
